import { Component, inject, Input, OnChanges } from '@angular/core';
import { AlertModule } from 'espd-common/alert';
import { EspdControl } from 'espd-common/forms/api';
import { MessageModule, MessageService } from 'espd-common/i18n';

@Component({
	selector: 'espd-errors',
	templateUrl: './errors.component.html',
	imports: [
		AlertModule,
		MessageModule
	],
	styles: [`:host {
		display: block;
	}`]
})
export class ErrorsComponent implements OnChanges {
	@Input()
	public control?: EspdControl;

	// eslint-disable-next-line @angular-eslint/no-input-rename
	@Input('messages')
	public messageMap!: Record<string, string | [string, unknown]>;

	public combinedMessages!: Record<string, string | [string, unknown]>;

	private defaultMessages: Record<string, string> = {
		required: 'common.validation.required',
		unique: 'common.validation.unique',
		pattern: 'common.validation.uniqueKey.pattern',
		equalTo: 'common.validation.match',
		url: 'common.validation.url',
		arrayMaxLength: 'common.validation.arrayMaxLength'
	};

	private messageService = inject(MessageService);

	public ngOnChanges(): void {
		this.combinedMessages = { ...this.defaultMessages, ...this.messageMap };
	}

	public get errorMessages(): string[] {
		const messages: string[] = [];
		if (this.control?.errors) {
			const errorKeys: string[] = Object.keys(this.control.errors);
			for (const validatorKey of errorKeys) {
				const messageValue: string | [string, unknown] = this.combinedMessages[validatorKey];
				if (messageValue) {
					if (typeof messageValue === 'string') {
						messages.push(this.messageService.get(messageValue));
					} else {
						const messageArgs = messageValue[1];
						messages.push(this.messageService.get(messageValue[0], ...(Array.isArray(messageArgs) ? messageArgs as unknown[] : [messageArgs])));
					}
				}
			}
		}
		return messages;
	}
}